/**
 * Tiny REAL image files (48x32 px) produced by Chrome's own canvas encoders, stored as base64.
 * `alphaCorner: true` means the top-left quarter is fully transparent.
 */
export const FIXTURES = {
  jpeg: {
    type: 'image/jpeg',
    width: 48,
    height: 32,
    alphaCorner: false,
    b64: '',
  },
  png: {
    type: 'image/png',
    width: 48,
    height: 32,
    alphaCorner: true,
    b64: '',
  },
  webpLossy: {
    type: 'image/webp',
    width: 48,
    height: 32,
    alphaCorner: false,
    b64: '',
  },
  webpAlpha: {
    type: 'image/webp',
    width: 48,
    height: 32,
    alphaCorner: true,
    b64: '',
  },
  webpLossless: {
    type: 'image/webp',
    width: 48,
    height: 32,
    alphaCorner: false,
    b64: '',
  },
};

export const fixtureBytes = (key) => Uint8Array.from(Buffer.from(FIXTURES[key].b64, 'base64'));
